[CmdletBinding()]param([string]$Root=(Get-Location).Path)
$ErrorActionPreference='Stop';$base=Join-Path $Root 'ES/Automation/WebPageStudio';$args=@{NetworkReceiptPath=(Join-Path $base 'fixtures/network-receipt.accepted.synthetic.json');PreviewReceiptPath=(Join-Path $base 'fixtures/preview-receipt.accepted.synthetic.json');VisualReceiptPath=(Join-Path $base 'fixtures/visual-receipt.accepted.synthetic.json');ReleaseReceiptPath=(Join-Path $base 'fixtures/release-receipt.accepted.synthetic.json');TaskId='synthetic-accepted';FocusKey='web-ui-focus'};$raw=& (Join-Path $base 'Invoke-ESWebUiEvidenceAggregate.ps1') @args;$aggregate=$raw|ConvertFrom-Json;if($aggregate.decision -ne 'accepted' -or $aggregate.layers.Count -ne 4 -or @($aggregate.layers|Where-Object validatorStatus -ne 'passed').Count -ne 0){throw 'ACCEPTED_SYNTHETIC_AGGREGATE_FAILED'};$tmp=[IO.Path]::GetTempFileName();try{[IO.File]::WriteAllText($tmp,($aggregate|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$projection=& (Join-Path $base 'Convert-ESWebUiAggregateToABCD.ps1') -AggregatePath $tmp -TaskId 'synthetic-accepted' -FocusKey 'web-ui-focus'|ConvertFrom-Json;if(-not $projection.promotionAllowed -or -not $projection.verificationEvent.readyForABCD){throw 'ABCD_ACCEPTED_PROJECTION_NOT_READY'}}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};[ordered]@{validator='web-ui-accepted-synthetic-path';status='passed';decision=[string]$aggregate.decision;layerCount=$aggregate.layers.Count;abcdReady=[bool]$projection.verificationEvent.readyForABCD;runtimeStatus='runtime-not-run';nonClaims=@('synthetic-algorithm-fixture','does-not-prove-runtime-or-release')}|ConvertTo-Json -Depth 8
